export interface Metric {
  id: string;
  label: string;
  unit: string;
}

export interface DashboardState {
  nodes: string[];
  query: Record<string, unknown>;
  loading: boolean;
  metrics: Metric[];
}

export type DashboardAction =
  | { type: "ADD_NODES"; ids: readonly string[] }
  | { type: "SET_QUERY"; query: Readonly<Record<string, unknown>> }
  | { type: "BEGIN_LOAD" }
  | { type: "RESET" }
  | { type: "SET_METRICS"; metrics: readonly Metric[] };

const blank = (value: string): boolean => value.trim().length === 0;
const copyMetrics = (metrics: readonly Metric[]): Metric[] => metrics.map((item) => ({ ...item }));

export function createInitialDashboardState(): DashboardState {
  return { nodes: [], query: {}, loading: false, metrics: [] };
}

export function dashboardReducer(state: DashboardState, action: DashboardAction): DashboardState {
  switch (action.type) {
    case "ADD_NODES": {
      if (action.ids.some(blank)) throw new RangeError("node IDs must not be blank");
      const seen = new Set(state.nodes);
      const nodes = [...state.nodes, ...action.ids.filter((id) => !seen.has(id))];
      return { ...state, nodes, query: { ...state.query }, metrics: copyMetrics(state.metrics) };
    }
    case "SET_QUERY":
      return {
        ...state,
        nodes: [...state.nodes],
        query: { ...action.query },
        metrics: copyMetrics(state.metrics),
      };
    case "BEGIN_LOAD":
      return {
        ...state,
        nodes: [...state.nodes],
        query: { ...state.query },
        loading: true,
        metrics: copyMetrics(state.metrics),
      };
    case "RESET":
      return createInitialDashboardState();
    case "SET_METRICS":
      if (action.metrics.some((item) => blank(item.id) || blank(item.label) || blank(item.unit))) {
        throw new RangeError("invalid metric");
      }
      return {
        ...state,
        nodes: [...state.nodes],
        query: { ...state.query },
        metrics: copyMetrics(action.metrics),
      };
    default:
      return {
        ...state,
        nodes: [...state.nodes],
        query: { ...state.query },
        metrics: copyMetrics(state.metrics),
      };
  }
}

