import * as S from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function deepEqual(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) throw new Error(message);
}
function throwsRange(fn: () => unknown, message: string): void {
  try { fn(); } catch (error) {
    if (error instanceof RangeError) return;
    throw new Error(`${message}: wrong error type`);
  }
  throw new Error(`${message}: expected RangeError`);
}

const initial = S.createInitialDashboardState();
deepEqual(initial.nodes, [], 'initial nodes');
deepEqual(initial.metrics, [], 'initial metrics');
deepEqual(initial.query, {}, 'initial query');
equal(initial.loading, false, 'initial loading');
const anotherInitial = S.createInitialDashboardState();
assert(initial !== anotherInitial, 'initial state is fresh');
assert(initial.nodes !== anotherInitial.nodes, 'initial node array is fresh');
assert(initial.metrics !== anotherInitial.metrics, 'initial metric array is fresh');
assert(initial.query !== anotherInitial.query, 'initial query object is fresh');

const ids = ['a', 'b', 'a', ' c ', 'b'];
const addAction = { type: 'ADD_NODES', ids } as S.DashboardAction;
const withNodes = S.dashboardReducer(initial, addAction);
deepEqual(withNodes.nodes, ['a', 'b', ' c '], 'nodes are deduplicated in first-occurrence order');
deepEqual(ids, ['a', 'b', 'a', ' c ', 'b'], 'payload IDs are not mutated');
equal(initial.nodes.length, 0, 'previous nodes are not mutated');
assert(withNodes !== initial, 'ADD_NODES returns a new state');
const appended = S.dashboardReducer(withNodes, { type: 'ADD_NODES', ids: ['b', 'd', 'd', 'a', 'e'] } as S.DashboardAction);
deepEqual(appended.nodes, ['a', 'b', ' c ', 'd', 'e'], 'existing IDs participate in deduplication');
const emptyAdd = S.dashboardReducer(appended, { type: 'ADD_NODES', ids: [] } as S.DashboardAction);
assert(emptyAdd !== appended, 'empty ADD_NODES still returns new state');
deepEqual(emptyAdd.nodes, appended.nodes, 'empty ADD_NODES preserves values');
throwsRange(() => S.dashboardReducer(initial, { type: 'ADD_NODES', ids: ['ok', '  '] } as S.DashboardAction), 'blank node ID');

const query = { term: ' shoes ', page: 0 };
const queryAction = { type: 'SET_QUERY', query } as unknown as S.DashboardAction;
const queried = S.dashboardReducer(withNodes, queryAction);
deepEqual(queried.query, query, 'query values are replaced');
assert(queried.query !== query, 'query is shallow-copied');
query.term = 'changed';
equal((queried.query as any).term, ' shoes ', 'later action mutation is isolated');
equal((initial.query as any).term, undefined, 'previous query is untouched');

const loading = S.dashboardReducer(queried, { type: 'BEGIN_LOAD' } as S.DashboardAction);
equal(loading.loading, true, 'BEGIN_LOAD sets loading');
assert(loading !== queried, 'BEGIN_LOAD returns a new state');

const metrics = [
  { id: 'm1', label: ' Requests ', unit: 'count' },
  { id: ' m2 ', label: 'Latency', unit: ' ms ' }
] as unknown as S.Metric[];
const metricsState = S.dashboardReducer(loading, { type: 'SET_METRICS', metrics } as S.DashboardAction);
deepEqual(metricsState.metrics, metrics, 'metrics are replaced without normalization');
assert(metricsState.metrics !== metrics, 'metric array is copied');
assert(metricsState.metrics[0] !== metrics[0], 'metric objects are copied');
(metrics[0] as any).label = 'changed';
equal((metricsState.metrics[0] as any).label, ' Requests ', 'metric input mutation is isolated');
assert(S.dashboardReducer(metricsState, { type: 'SET_METRICS', metrics: [] } as S.DashboardAction) !== metricsState, 'empty metrics action returns a new state');
for (const field of ['id', 'label', 'unit']) {
  const metric = { id: 'id', label: 'label', unit: 'unit', [field]: '\t' };
  throwsRange(() => S.dashboardReducer(initial, { type: 'SET_METRICS', metrics: [metric] } as unknown as S.DashboardAction), `blank metric ${field}`);
}

const reset = S.dashboardReducer(metricsState, { type: 'RESET' } as S.DashboardAction);
deepEqual(reset, S.createInitialDashboardState(), 'RESET returns initial values');
assert(reset !== initial, 'RESET returns a fresh state');
assert(reset.nodes !== initial.nodes && reset.metrics !== initial.metrics && reset.query !== initial.query, 'RESET nested containers are fresh');

const unknown = S.dashboardReducer(metricsState, { type: 'RUNTIME_UNKNOWN' } as unknown as S.DashboardAction);
assert(unknown !== metricsState, 'unknown runtime action returns a new top-level state');
deepEqual(unknown, metricsState, 'unknown runtime action preserves values');

